using Monergy.Platform;
using Monergy.Services.Evidence.Application;
namespace Monergy.Services.Evidence.Infrastructure;
public sealed partial class InMemoryEvidenceRepository:IDocumentMonitoringRepository
{
 public Task<DocumentMonitorPage> MonitorAsync(DocumentMonitorScope scope,DocumentMonitorQuery query,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();DocumentMonitoring.Query(query);lock(sync){var all=versions.Values.Where(scope.Owns).Where(x=>(query.CustomerId is null||x.CustomerId==query.CustomerId)&&(query.DocumentId is null||x.DocumentId==query.DocumentId)).ToArray();var filtered=all.Where(x=>(query.Scan=="all"||(DocumentMonitoring.Scanned(x)?"VERIFIED_AT_INTAKE":"UNRECORDED")==query.Scan)&&(x.OriginalFileName.Contains(query.Search,StringComparison.OrdinalIgnoreCase)||x.DocumentId.Contains(query.Search,StringComparison.OrdinalIgnoreCase)||x.DocumentVersionId.Contains(query.Search,StringComparison.OrdinalIgnoreCase))).ToArray();IEnumerable<EvidenceVersionRecord> page=filtered.OrderByDescending(x=>x.CreatedAt).ThenByDescending(x=>x.DocumentVersionId,StringComparer.Ordinal);if(query.After is not null){var cursor=versions.GetValueOrDefault(query.After);if(cursor is null||!scope.Owns(cursor)||query.CustomerId is not null&&cursor.CustomerId!=query.CustomerId||query.DocumentId is not null&&cursor.DocumentId!=query.DocumentId)throw new TenantBoundaryException("DOCUMENT_MONITOR_CURSOR_INVALID",400);page=page.Where(x=>x.CreatedAt<cursor.CreatedAt||x.CreatedAt==cursor.CreatedAt&&StringComparer.Ordinal.Compare(x.DocumentVersionId,cursor.DocumentVersionId)<0);}var rows=page.Take(51).ToArray();return Task.FromResult(new DocumentMonitorPage(scope.TenantId,rows.Take(50).Select(x=>DocumentMonitoring.View(scope,x)).ToArray(),rows.Length>50?rows[49].DocumentVersionId:null,filtered.LongLength,all.LongLength,all.LongCount(DocumentMonitoring.Scanned),all.LongCount(x=>!DocumentMonitoring.Scanned(x))));}}
 public Task<MonitoredDocument?> MonitorReadAsync(DocumentMonitorScope scope,string versionId,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();lock(sync){var row=versions.GetValueOrDefault(versionId);return Task.FromResult(row is not null&&scope.Owns(row)?DocumentMonitoring.View(scope,row):null);}}
}
